import{_ as p,a0 as o,w as l,s as d,ao as c,I as t,x as a,a1 as i,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"在 Linux 文件系統中導航的技巧 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 文件系統中導航的技巧 | LCTT (202005) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 文件系統中導航的技巧 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 文件系統中導航的技巧 | LCTT (202005) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202005/20200326 Tricks for getting around your Linux file system","title":"在 Linux 文件系統中導航的技巧","tag":"202005","desc":""},"relativePath":"202005/20200326 Tricks for getting around your Linux file system.md","filePath":"[post].md"}'),r={name:"202005/20200326 Tricks for getting around your Linux file system.md"};function h(g,s,u,k,b,m){const e=o("Link");return l(),d("div",null,[s[15]||(s[15]=c(`<h1 id="在-linux-文件系統中導航的技巧" tabindex="-1">在 Linux 文件系統中導航的技巧 <a class="header-anchor" href="#在-linux-文件系統中導航的技巧" aria-label="Permalink to “在 Linux 文件系統中導航的技巧”">​</a></h1><blockquote><p>cd 命令可能是任何 Linux 用户學習的前 10 個命令之一，但這並不是在 Linux 文件系統中導航的唯一方法，這裏還有其他一些方法。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202005/22/114058yrzlx94rz9lbx974.jpg" alt=""></p><p>無論你是在文件系統中四處查看、尋找文件還是嘗試進入重要目錄，Linux 都可以提供很多幫助。在本文中，我們將介紹一些技巧，使你可以在文件系統中移動，查找和使用所需的命令也更加輕鬆。</p><h3 id="添加到-path" tabindex="-1">添加到 $PATH <a class="header-anchor" href="#添加到-path" aria-label="Permalink to “添加到 $PATH”">​</a></h3><p>確保你不必花費大量時間在 Linux 系統上查找命令的最簡單、最有用的方法之一就是在 <code>$PATH</code> 變量中添加適當的目錄。但是，添加到 <code>$PATH</code> 變量中的目錄順序非常重要。它們確定系統在目錄中查找要運行命令的目錄順序--在找到第一個匹配項時停止。</p><p>例如，你可能希望將家目錄放在第一個，這樣，如果你創建的腳本與其他可執行文件有相同的名稱，那麼只要輸入該腳本的名稱，它便會運行。</p><p>要將家目錄添加到 <code>$PATH</code> 變量中，可以執行以下操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ export PATH=~:$PATH</span></span></code></pre></div><p><code>~</code> 字符代表家目錄。</p><p>如果將腳本保存在 <code>bin</code> 目錄中，下面的會有效：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ export PATH=~/bin:$PATH</span></span></code></pre></div><p>然後，你可以運行位於家目錄中的腳本，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ myscript</span></span>
<span class="line"><span>Good morning, you just ran /home/myacct/bin/myscript</span></span></code></pre></div><p><strong>重要提示：</strong>上面顯示的命令會添加到你的搜索路徑中，因為 <code>$PATH</code>（當前路徑）被包含在內。它們不會覆蓋它。你的搜索路徑應該在你的 <code>.bashrc</code> 文件中配置，任何你打算永久化的更改也應該添加到那裏。</p><h3 id="使用符號鏈接" tabindex="-1">使用符號鏈接 <a class="header-anchor" href="#使用符號鏈接" aria-label="Permalink to “使用符號鏈接”">​</a></h3><p>符號鏈接提供了一種簡單而明顯的方式來記錄可能經常需要使用的目錄的位置。例如，如果你管理網站的內容，那麼可能需要通過創建如下鏈接來使你的帳户“記住”網頁文件的位置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ln -s /var/www/html www</span></span></code></pre></div><p>參數的順序很重要。第一個（<code>/var/www/html</code>）是目標，第二個是你創建的鏈接的名稱。如果你當前不在家目錄中，那麼以下命令將執行相同的操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ln -s /var/www/html ~/www</span></span></code></pre></div><p>設置好之後，你可以使用 <code>cd www</code> 進入 <code>/var/www/html</code>。</p><h3 id="使用-shopt" tabindex="-1">使用 shopt <a class="header-anchor" href="#使用-shopt" aria-label="Permalink to “使用 shopt”">​</a></h3><p><code>shopt</code> 命令還提供了一種讓移動到其他目錄更加容易的方法。當你使用 <code>shopt</code> 的 <code>autocd</code> 選項時，只需輸入名稱即可轉到目錄。例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ shopt -s autocd</span></span>
<span class="line"><span>$ www</span></span>
<span class="line"><span>cd -- www</span></span>
<span class="line"><span>/home/myacct/www</span></span>
<span class="line"><span>$ pwd -P</span></span>
<span class="line"><span>/var/www/html</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ ~/bin</span></span>
<span class="line"><span>cd -- /home/myacct/bin</span></span>
<span class="line"><span>$ pwd</span></span>
<span class="line"><span>/home/myacct/bin</span></span></code></pre></div><p>在上面的第一組命令中，啓用了 <code>shopt</code> 命令的 <code>autocd</code> 選項。輸入 <code>www</code>，就會調用 <code>cd www</code> 命令。由於此符號鏈接是在上面的 <code>ln</code> 命令示例之一中創建的，因此將我們移至 <code>/var/www/html</code>。 <code>pwd -P</code> 命令顯示實際位置。</p><p>在第二組中，鍵入 <code>~/bin</code> 會調用 <code>cd</code> 進入在用户家目錄的 <code>bin</code> 目錄。</p><p>請注意，當你輸入的是命令時，<code>autocd</code> 行為將<em>不會</em>生效，即使它也是目錄的名稱。</p><p><code>shopt</code> 是 bash 內置命令，它有很多選項。這只是意味着你不必在要進入每個目錄的名稱之前輸入 <code>cd</code>。</p><p>要查看 <code>shopt</code> 的其他選項，只需輸入 <code>shopt</code>。</p><h3 id="使用-cdpath" tabindex="-1">使用 $CDPATH <a class="header-anchor" href="#使用-cdpath" aria-label="Permalink to “使用 $CDPATH”">​</a></h3><p>可能進入特定目錄的最有用技巧之一，就是將你希望能夠輕鬆進入的路徑添加到 <code>$CDPATH</code> 中。這將創建一個目錄列表，只需輸入完整路徑名的一部分即可進入。</p><p>一方面，這可能有點棘手。你的 <code>$CDPATH</code> 需要包含要移動到的目錄的父目錄，而不是目錄本身。</p><p>例如，假設你希望僅通過輸入 <code>cd html</code> 就可以移至 <code>/var/www/html</code> 目錄，並僅使用 <code>cd</code> 和簡單目錄名即可移至 <code>/var/log</code> 中的子目錄。在這種情況下，此 <code>$CDPATH</code> 就可以起作用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ CDPATH=.:/var/log:/var/www</span></span></code></pre></div><p>你將看到：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd journal</span></span>
<span class="line"><span>/var/log/journal</span></span>
<span class="line"><span>$ cd html</span></span>
<span class="line"><span>/var/www/html</span></span></code></pre></div><p>當你輸入的不是完整路徑時，<code>$CDPATH</code> 就會生效。它向下查看其目錄列表，以查看指定的目錄是否存在於其中一個目錄中。找到匹配項後，它將帶你到那裏。</p><p>在 <code>$CDPATH</code> 開頭保持 <code>.</code> 意味着你可以進入本地目錄，而不必在 <code>$CDPATH</code> 中定義它們。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ export CDPATH=&quot;.:$CDPATH&quot;</span></span>
<span class="line"><span>$ Videos</span></span>
<span class="line"><span>cd -- Videos</span></span>
<span class="line"><span>/home/myacct/Videos</span></span></code></pre></div><p>在 Linux 文件系統鍵切換並不難，但是如果你使用一些方便的技巧輕鬆地到達各個位置，那你可以節省一些大腦細胞。</p><hr>`,41)),t("p",null,[s[1]||(s[1]=a("via: ",-1)),i(e,{href:"https://www.networkworld.com/article/3533421/tricks-for-getting-around-your-linux-file-system.html"},{default:n(()=>[...s[0]||(s[0]=[a("https://www.networkworld.com/article/3533421/tricks-for-getting-around-your-linux-file-system.html",-1)])]),_:1})]),t("p",null,[s[6]||(s[6]=a("作者：",-1)),i(e,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:n(()=>[...s[2]||(s[2]=[a("Sandra Henry-Stocker",-1)])]),_:1}),s[7]||(s[7]=a(" 選題：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 譯者：",-1)),i(e,{href:"https://github.com/geekpi"},{default:n(()=>[...s[4]||(s[4]=[a("geekpi",-1)])]),_:1}),s[9]||(s[9]=a(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:n(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[12]||(s[12]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:n(()=>[...s[11]||(s[11]=[a("Linux中國",-1)])]),_:1}),s[14]||(s[14]=a(" 榮譽推出",-1))])])}const y=p(r,[["render",h]]);export{x as __pageData,y as default};
